$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	dc.b $FF,$FF,$FF,$FF,$FF,$FF,$FF	EndP********************************************************************************* DrawStringWidth -- new call 5-Mar-92 DAL for 6.0.1** Description:*   Draws a string to fit in a particular width, compressing or truncating*   the string as necessary.** Inputs:*   WORD  flags*      bit 15 = disallow compression*      bits 14-13 = truncate: none/left/center/right*      bits 3-2 = 00=pstring, 01=cstring, 10=wstring*      bits 1-0 = 00=pointer, 01=handle, 10=resource*   LONG  stringRef (ptr, handle, rID)*   WORD  width** When the string is by handle, we lock it during the call and then* restore its former attributes.** When the string is by resource (rPString, rCString, rWString), we preserve* and restore its attributes if it was already in memory.  If it wasn't, we* release it to purge level when we're done.********************************************************************************DrawStringWidth	proc	phd	pha	;space for length2	pha	;space for position2	pha	;space for length1	pha	;space for position1	pha	;space for strLength	pha	;space for oldAttr	pha	pha	;space for ptr	tsc	tcdptr	equ 1oldAttr	equ ptr+4strLength	equ oldAttr+2position1	equ strLength+2length1	equ position1+2position2	equ length1+2length2	equ position2+2oldD	equ length2+2rtl1	equ oldD+2rtl2	equ rtl1+3theWidth	equ rtl2+3stringRef	equ theWidth+2flags	equ stringRef+4	jsr GetStringPtr	bcs @error	pha	pha	;space for GetCharExtra	_GetCharExtra	jsr SetupString	;set up <strLength and adjust <ptr;; If allowed and necessary, set CharExtra to -1 to crunch horizontally;	bit <flags	bmi @noCrunch	jsr GetWidth	cmp <theWidth	bcc @noCrunch	beq @noCrunch	pea $ffff	pea 0	_SetCharExtra@noCrunch	jsr Truncate; if both chunks are empty, don't draw anything	lda <length1	ora <length2	beq @noDraw; draw chunk 1 if nonempty	ldy <length1	beq @skip1	lda <position1	jsr drawChunk@skip1; draw ellipsis if anything was truncated	clc	lda <length1	adc <length2	cmp <strLength	beq @noEllipsis	pea $00C9	;ellipsis	_DrawChar@noEllipsis; draw chunk 2 if nonempty	ldy <length2	beq @skip2	lda <position2	jsr drawChunk@skip2@noDraw	_SetCharExtra	jsr ReleaseString	ldx #0	;no error@error	pla	pla	;discarded ptr	pla	;discarded oldAttr	pla	;discarded strLength	pla	;discarded position1	pla	;discarded length1	pla	;discarded position2	pla	;discarded length2	pld	ldy #8	;strip 8 bytes	jml >$e10184	;ToStrip;; Truncate;; Input:  ptr, strLength;         flags (truncation mode in bits 14-13);         theWidth (available pixel width);; Output: position1, length1;         position2, length2;Truncate	stz <position1	stz <position2	stz <length2	lda <strLength	sta <length1	lda <flags	and #$6000	beq @none	jsr GetWidth	cmp <theWidth	bcc @none	beq @none	pha	pea $00c9	_CharWidth	pla	eor #$ffff	inc a	clc	adc <theWidth	sta <theWidth	lda <flags	and #$6000	xba	;trunc mode in bits 6-5	lsr a	lsr a	lsr a	lsr a	tax	jmp (@trunc,x)@trunc	dc.w @none,@left,@center,@right@none	rts;; Do truncation on the left;; Right-justify chunk 2 to theWidth (compute position2, length2);@left	stz <length1	;zap chunk 1	lda <strLength	sta <length2@rightChopping	inc <position2	dec <length2	beq @rightDone	pha	;space for TextWidth	ldx <ptr+2	lda <ptr	clc	adc <position2	bcc @1	inx@1	phx	pha	pei <length2	_TextWidth	pla	cmp <theWidth	beq @rightDone	bcs @rightChopping@rightDone	rts;; Do truncation on the right;; Left-justify chunk 1 to theWidth (compute length1);@right	lda <strLength	sta <length1@leftChopping	dec <length1	beq @leftDone	pha	;space for TextWidth	pei <ptr+2	pei <ptr	pei <length1	_TextWidth	pla	cmp <theWidth	beq @leftDone	bcs @leftChopping@leftDone	rts;; Center--cut the width in half and compute left and;         right chunks to theWidth;@center	lsr <theWidth	jsr @left	jsr @right	rts;; DrawChunk;; Input:  A = position within <ptr;         Y = length to draw;DrawChunk	ldx <ptr+2	clc	adc <ptr	bcc @1	inx@1	phx	pha	phy	_DrawText	rts;; GetStringPtr;; Input:  stringRef, flags; Output: SEC/X=error;         ptr = string pointer (locked);         stringRef is handle if it was a resource ID;         oldAttr = handle's old attributes;; Flags, bits 0-1 = pointer/handle/resource;GetStringPtr	lda <flags	and #$0003	asl a	tax	jmp (@get,x)@get	dc.w @ptr,@handle,@resource,@error@ptr	lda <stringRef+2	ldx <stringRef	sta <ptr+2	stx <ptr	clc	rts@resource	pha	pha	;space for LoadResource2	lda #0	pha	;flags = 0	pha	;buffer bank = 0	tdc	clc	adc #oldAttr	pha	;buffer = <oldAttr	jsr PushResType	pei <stringRef+2	pei <stringRef	_LoadResource2	plx	stx <stringRef	plx	stx <stringRef+2	bcc @continue	tax	rts@continue	ldy #4	lda <oldAttr	tax	inx	bne @lockAndDeref;; If the resource was not previously loaded, we'll later; release it to purge level 3;	lda [<stringRef],y	ora #$0300	;make it purge level 3	bra @lockAndDeref@handle	ldy #4	;handle attributes	lda [<stringRef],y@lockAndDeref	sta <oldAttr	;Y=4!!	lda [<stringRef],y	ora #$8000	;lock it	sta [<stringRef],y	dey	dey	;y=2	lda [<stringRef],y	sta <ptr+2	lda [<stringRef]	sta <ptr	clc	rts@error	ldx #badQDAuxValue	sec	rts;; PushResType;; Input:  flags bits 2-3 = pstring/cstring/wstring;PushResType	lda <flags	and #$000c	lsr a	tax	lda >@resTypes,x	plx	pha	phx	rts@resTypes	dc.w rPString,rCString,rWString,$FFFF;; ReleaseString;; Pointer:  does nothing; Handle:   restore attributes; Resource: restore attributes;; Flags bits 0-1 = pointer/handle/resource;ReleaseString	lda <flags	and #$0003	beq @nothing;; For handle or resource, restore old attributes;	lda <oldAttr	ldy #4	sta [<stringRef],y@nothing	rts;; SetupString;; Input:  ptr, flags bits 2-3 = pstring/cstring/wstring;SetupString	lda <flags	and #$000C	lsr a	tax	jmp (@setup,x)@setup	dc.w @pstring,@cstring,@wstring,@error@pstring	lda [<ptr]	and #$00ff	;get length	ldy #1	;inc ptr by 1	bra @common@wstring	lda [<ptr]	;get length	ldy #2	;inc ptr by 2@common	sta <strLength	tya	clc	adc <ptr	sta <ptr	bcc @1	inc <ptr+2@1	rts@cstring	ldy #-1@findEnd	iny	lda [<ptr],y	and #$00ff	bne @findEnd	sty <strLength	rts@error	brk 0;; GetWidth;; Input:  ptr, strLength; Output: A;GetWidth	pha	pei <ptr+2	pei <ptr	pei <strLength	_TextWidth	pla	rts	EndP********************************************************************************* UseColorTable -- new call 16-Mar-93 DAL for 6.0.1d15** $1612 UseColorTable(tableNum,@Table,Flags):ColorInfoHandle** Inputs:*   LONG  space for result (handle for restoring to old color table)*   WORD  tableNum (0..15)*   LONG  tablePtr (pointer to 32-byte color table)*   WORD  flags (see below)** TablePtr:*   Pointer to a 32-byte color table*   NIL for default for current mode (MasterSCB determines 640/320)** Flags:*   bit 15 = use the standard 640-mode colors, even in 320 mode (ignores tablePtr)*   bit 14 = don't call CtlNewRes*   bit 13 = include the menu bar*   bits 12..0 = reserved (use zero)*   (Could use bits 0..1 as pointer/handle/resource mode for the tablePtr parameter)** ResultH:  (Color Info Handle)*   Puts old color table & number & SCBs into OldH)**      +000: word        table number*      +002: 32 bytes    color table data*      +034: word        first scanline number saved*      +036: word        scanline count (or last scanline?)*      +038: bytes       saved SCBs********************************************************************************ciTableNum	equ 0ciColorTable	equ 2ciFirstScanline	equ 34ciLastScanline	equ 36ciSCBs	equ 38fUse640Colors	equ $8000fNoCtlNewRes	equ $4000fIncludeMenuBar	equ $2000UseColorTable	proccolorHandleSize	equ 38+200	;room for 200 SCBs	tax	phd	pha	pha	;space for ptr	pha	;space for myUserID	tsc	tcdmyUserID	equ 1ptr	equ myUserID+2	;local scratcholdD	equ ptr+4rtl1	equ oldD+2rtl2	equ rtl1+3flags	equ rtl2+3	;input parameterstablePtr	equ flags+2tableNum	equ tablePtr+4result	equ tableNum+2	;result space*** with WAP still in X, get QD User ID	lda >$0000000A,x	;offset to QD user ID	sta <myUserID	stz result	stz result+2	ldx #badQDAuxValue	lda <tableNum	and #$fff0	beq @ok@toError	brl @error@ok	pha	pha	;space for NewHandle result	pea 0	pea colorHandleSize	;size needed	pei <myUserID	pea $8010	;attributes (locked, no-bank-cross)	pha	pha	;location (ignored)	_NewHandle	tax	pulllong <result	bcs @toError	ldy #2	lda [<result],y	sta <ptr+2	lda [<result]	sta <ptr	lda <tableNum	sta [<ptr]	;saved at ciTableNum	pha	;table number for GetColorTable	pei <ptr+2	lda <ptr	inc a	inc a	;ciColorTable must be 2!	pha	;get color table into our handle (does not cross bank)	_GetColorTable	pha	_GetMasterSCB	pla	and #$0080	bne @not320	ldy #^Cool320Colors	ldx #Cool320Colors	bit <flags	bmi @UseYXcolors@not320	ldy <tablePtr+2	ldx <tablePtr	lda <tablePtr+1	bne @UseYXcolors	pushlong #StandardColors	_InitColorTable	ldy #^StandardColors	ldx #StandardColors@UseYXcolors	pei <tableNum	phy	phx	_SetColorTable***Êdone messing with color table; now mess with SCBs	lda <flags	jsr GetMenuBarHeight	ldy #ciFirstScanline	sta [<ptr],y	tax	;put starting line in X	iny	iny	lda #200	;last scanline	sta [<ptr],y*** advance <ptr to the SCB-save area	clc	lda <ptr	adc #ciSCBs	sta <ptr	txy@setSCBs	phy	pha	;space for GetSCB	phy	_GetSCB	pla	tax	and #$000f	;save only the color table bits	ply	phy	sep #$20	sta [<ptr],y	rep #$20	txa	ora <tableNum	;slap in the new color table number	ply	phy	phy	;push line #	pha	;push new SCB	_SetSCB	ply	iny	cpy #200	bcc @setSCBs	lda <flags	jsr doCtlNewRes	pei <result+2	pei <result	_HUnlock	ldx #0	;no error@error	pla	;discarded myUserID	pla	pla	;discarded ptr	pld	ldy #8	;strip 8 bytes	jml >$e10184	;ToStrip********************************************************************************* Cool320Table is a 320-mode color table that very closely* resembles the standard 640 dithered colors.********************************************************************************Cool320Colors	dc.w $0000,$0008,$0880,$0888	dc.w $0800,$0808,$0f80,$0f88	dc.w $0080,$0088,$08f0,$08f8	dc.w $0888,$088f,$0ff8,$0fffStandardColors	dc.w $7777,$7777,$7777,$7777	;changed by InitColorTable	dc.w $7777,$7777,$7777,$7777	dc.w $7777,$7777,$7777,$7777	dc.w $7777,$7777,$7777,$7777********************************************************************************* Get system menu bar height** Input: <flags in A********************************************************************************	export GetMenuBarHeightGetMenuBarHeight	ldx #0	and #fIncludeMenuBar	bne @done	pha	;word space for func result	pha	pha	;space for GetMenuBar	_GetMenuBar	lda #0	pha	pha	_SetMenuBar	;set to System menu bar (nil)*** If the bar is hidden, return zero	phd	pha	pha	_GetMenuBar	tsc	tcd	ldy #2	lda [1],y	tax	lda [1]	sta 1	stx 3	;dereference menu bar handle	ldy #$0010	lda [1],y	;get ctlFlag (bit 7 = invisible flag)	ply	ply	pld	eor #$0080	and #$0080	beq @zero	pha	_FixMenuBar	pla@zero	sta 1+4,s	_SetMenuBar	plx	;get FixMenuBar result@done	txa	rts********************************************************************************* doCtlNewRes** Call CtlNewRes, making sure a valid port is set.** Input: <flags in A********************************************************************************	export doCtlNewResdoCtlNewRes	and #fNoCtlNewRes	bne @done	pha	pha	_GetPort	pha	pha	pea 0	pea 4	_GetWAP	plx	pla; Look at $10A on QD Direct page to find the Handle to the First Port	lda >$10A+2,x	pha	lda >$10A,x	pha	phd	tsc	tcd	ldy #2	lda [3],y	tax	lda [3]	sta <3	stx <5	;dereferenced into Port Pointer	pld	_SetPort	_CtlNewRes	_SetPort@done	rts	EndP********************************************************************************* RestoreColorTable -- new call 16-Mar-93 DAL for 6.0.1d15** $1712 RestoreColorTable(ColorInfoHandle,Flags)** Description:** Inputs:*   LONG  handle to data for restore (must come from UseColorTable)*   WORD  flags** Flags:*   bit 15 = reserved, use 0*   bit 14 = don't call CtlNewRes*   bit 13 = include the menu bar*   bits 12..0 = reserved, use 0** Note:  If the ColorInfoHandle is NIL, we don't do anything.********************************************************************************RestoreColorTable	proc	import GetMenuBarHeight,doCtlNewRes	phd	pha	pha	;space for ptr	tsc	tcdptr	equ 1oldD	equ ptr+4rtl1	equ oldD+2rtl2	equ rtl1+3flags	equ rtl2+3theHandle	equ flags+2	ldx <theHandle+1	beq @error	;error code in X (no error)	ldy #4	lda [<theHandle],y	ora #$8000	;lock it	sta [<theHandle],y	dey	dey	lda [<theHandle],y	sta <ptr+2	lda [<theHandle]	sta <ptr	;dereferenced it*** Restore SCBs, starting from the menu bar height or the first saved line,*** whichever is bigger.	lda <flags	jsr GetMenuBarHeight	ldy #ciFirstScanline	cmp [<ptr],y	bcs @startHere	lda [<ptr],y@startHere	tay	;line number	clc	lda <ptr	pha	adc #ciSCBs	sta <ptr@restoreSCBs	phy	pha	;space for GetSCB	phy	_GetSCB	pla	and #$00f0	;keep mode bits	ply	phy	ora [<ptr],y	;slap in the old color table number	phy	;line number to set	pha	;new SCB value	_SetSCB	ply	iny	cpy #200	bcc @restoreSCBs	pla	sta <ptr	;restored <ptr*** done restoring SCBs; now restore the color table	lda [<ptr]	;table number to restore	pha	pei <ptr+2	clc	lda <ptr	adc #ciColorTable	pha	_SetColorTable	lda <flags	jsr doCtlNewRes	pei <theHandle+2	pei <theHandle	_DisposeHandle	tax@error	pla	pla	;discarded ptr	pld	ldy #6	;strip 6 bytes	jml >$e10184	;ToStrip	EndP	if NewPortKillPort then********************************************************************************* off-screen port routines -- Version 3.0** Copyright (c)* Apple Computer, Inc.  1989-1990* All Rights Reserved.** Written by Eric Soldan.** The purpose of this code is to make creating and disposing of off-screen* grafPorts more convenient.********************************************************************************** $1112 NewPort(pmapPortInfoPointer):GrafPortPtr** pmapPortInfo structure:* +000 portPtr* +004 portHndl* +008 pixMapPtr* +012 pixMapHndl* +014 pixMapAttr* +016 portRect* +024 pixMapRect********************************************************************************NewPort	PROC export	import KillPort	DefineStackkeepPort	long	;Must be at 1,s.portPtr	long	;Pass NULL if mem needed for port.portHndl	longbitMapPtr	long	;Pass NULL if mem needed for bitMap.bitMapHndl	longbitMapAttr	word	;Memory attributes for bitMap.ourPortRect	block 8bitMapRect	block 8endDesc	block 0	;Descriptor locals end here.portInfo	block oportRect-oportInfobitMapHeight	wordbmPtr	long	;Pointer to bitMap, if we made one.tempPtr	long	;Temporary bitMap work pointer.npUserID	word	;added 19-Jan-91 DALsizeLocals	EndLocalssaveDPage	wordreturnAddr	block 6	;used to be block 3 (DAL)	BegParmsportDescPtr	long	;Pointer to port descriptor.sizeParms	EndParmsretval	long	;We will return the new grafPortPtr.	tax	;keep WAP handy (DAL)	phd	;Save directPage register.	tsc	;Make space for locals.	sec	sbc #sizeLocals	tcd	;Set directPage register.	tcs*** with WAP still in X, get QD User ID and put it in <npUserID (19-Jan-91 DAL)	lda >$0000000A,x	;offset to QD user ID	sta <npUserID***	_GetPort	;keepPort is result space.	ldy #endDesc-portPtr-2@a	tyx	;Copy descriptor data into directPage.	lda [portDescPtr],y	sta portPtr,x	dey	dey		bpl @a	stz portHndl	;Flag that we don't have handles yet.	stz portHndl+2	stz bitMapHndl	stz bitMapHndl+2	stz retval	;Assume we fail.	stz retval+2	lda portPtr+1	;See if we were passed a port pointer.	bne @givenPortMem	;We were.	pha	;Result space.	pha	pea portSize>>16	;Size of handle.	pea portSize	pei <npUserID	;19-Jan-91 DAL	pea attrLocked+attrFixed+attrNoCross	pha	;location doesn't matter	pha	_NewHandle	plx	ply	bcc @havePortHndl	;We succeeded at creating a port handle.	brl @exit	;Failed because we couldn't get memory.@havePortHndl	stx portHndl	;We succeeded, so save the handle.	sty portHndl+2	ldy #2	;Dereference the handle to a grafPortPtr.	lda [portHndl]	sta portPtr	lda [portHndl],y	sta portPtr+2@givenPortMem	pei portPtr+2	;Now that we have grafPort mem, in either	pei portPtr	;case, try opening the port.	_OpenPort	bcc @portOpened	;Hey, it worked!	tay	;Keep error code.	lda #$8000	;This flag indicates that the _OpenPort	tsb portHndl+2	;failed.  If it failed, we should not		;do a _ClosePort.	tya	;Restore error code.	brl @exit	;Failed because we couldn't get memory.@portOpened	pha	;Push parms to make visRgn rectangular.	pha	_GetVisHandle	pea 0	tdc	clc	adc #ourPortRect	pha	_RectRgn*** Note: This was buggy in the DTS version.  Was calling RectRgn with garbage once.	pha	;Push parms to make clipRgn rectangular.	pha	_GetClipHandle	pea 0	tdc	clc	adc #ourPortRect	pha	_RectRgn	pea 0	;Get the new port's locInfo structure.	tdc	clc	adc #portInfo	pha	_GetPortLoc	lda bitMapRect+oh2	;Get width of bitMap rectangle.	sec	sbc bitMapRect+oh1	ldx portInfo+oportSCB-1		;Check bit 7 of the portSCB.	bmi @b	;The -1 is so we can bmi test.	asl a	;Pretend it is 640 for below math.@b	clc	;Convert 640 width into rowBytes.	adc #3	lsr a	lsr a	clc	adc #7	and #$FFF8	sta portInfo+owidth	ldx bitMapPtr+1	;See if we need to make a bitMap.	bne @givenBitMapMem	;We don't need to.	pha	;Result space for _NewHandle	pha	pha	;Result space for _Multiply	pha	pha	;_Multiply param 1 (acc is still width).	lda bitMapRect+ov2	sec	sbc bitMapRect+ov1	sta bitMapHeight	pha	;_Multiply param 2	_Multiply	pei <npUserID	;19-Jan-91 DAL	pei bitMapAttr	;Memory attributes for bitMap.	pha	;location doesn't matter	pha	_NewHandle	plx	ply	bcs @exit	;Failed because we couldn't get memory.	stx bitMapHndl	sty bitMapHndl+2	ldy #2	;Dereference bit Map handle.	lda [bitMapHndl]	sta bmPtr	sta tempPtr	lda [bitMapHndl],y	sta bmPtr+2	sta tempPtr+2	ldx bitMapHeight	;Fill bitMap with white.@white1	lda #$FFFF	ldy portInfo+owidth@white2	dey	dey	sta [tempPtr],y	bne @white2	lda tempPtr	clc	adc portInfo+owidth	sta tempPtr	bcc @ok	inc tempPtr+2@ok	dex	bne @white1@givenBitMapMem	ldx #6	;Copy the bounds rect into locInfo.@moveBounds	lda bitMapRect,x	sta portInfo+oboundsRect,x	dex	dex	bpl @moveBounds	lda bitMapPtr+2	bmi @defaultBitMap	;Use QuickDraw default bitMap pointer.	ldx bitMapPtr	ldy bitMapPtr+2	lda bitMapPtr+1	bne @passedBitMap	;Use bitMap pointer declared by application.	ldx bmPtr	;Use pointer to bitMap we made.	ldy bmPtr+2@passedBitMap	stx portInfo+optrToPixImage	sty portInfo+optrToPixImage+2@defaultBitMap	pea 0	;Set the portLoc, now that we have	tdc	;finished setting it up.	clc	adc #portInfo	pha	_SetPortLoc	pea 0	;Set the portRect to the passed rect.	tdc	clc	adc #ourPortRect	pha	_SetPortRect	lda portPtr	;Everything worked, so pass back the	sta retval	;new grafPort pointer, instead of NULL.	lda portPtr+2	sta retval+2	clc	;We had no error.@exit	ldy #0	;Assume no error.	bcc @noError	;Hey, we were right!@error	pha	;Keep error code.	pei portDescPtr+2	pei portDescPtr	jsl KillPort	;Dispose everything that was created.	ply	;Restore error code.@noError	phy	;Keep error code (if any).	pei keepPort+2	;Restore the port.	pei keepPort	_SetPort	ldy #endDesc-portPtr-2@c	tyx	;Update the port descriptor.	lda portPtr,x	sta [portDescPtr],y	dey	dey	bpl @c***	ply	;Restore error code (if any).	plx	;get error code in X	tsc	;Get rid of local variables.	clc	adc #sizeLocals	tcs	pld	;Restore directPage register.;	lda 1,s	;Move return address.;	sta 1+sizeParms,s;	lda 2,s;	sta 2+sizeParms,s;	tsc	;Get rid of passed parameters.;	adc #sizeParms;	tcs;	tya;	cmp #1	;Set error status correctly.;	rtl	ldy #sizeParms	jml $e10184	;ToStrip	ENDP********************************************************************************* $1212 KillPort(pmapInfoPointer)** Kills a port created with NewPort.********************************************************************************KillPort	PROC export	DefineStackportPtr	long	;Pass NULL if mem needed for port.portHndl	longbitMapPtr	long	;Pass NULL if mem needed for bitMap.bitMapHndl	longendDesc	block 0	;Descriptor locals end here.		;We don't need the entire descriptor.sizeLocals	EndLocalssaveDPage	wordreturnAddr	block 6	;was block 3 (DAL)	BegParmsportDescPtr	long	;Pointer to port descriptor.sizeParms	EndParms	phd	;Save directPage register.	tsc	;Make space for locals.	sec	sbc #sizeLocals	tcd	;Set directPage register.	tcs	;Allow us to use 0 as directPage address.	ldy #endDesc-portPtr-2@a	tyx	;Copy descriptor data into directPage.	lda [portDescPtr],y	sta portPtr,x	dey	dey		bpl @a	lda bitMapHndl+1	beq @notOurBitMap	pei bitMapHndl+2	pei bitMapHndl	_DisposeHandle@notOurBitMap	lda portHndl+2	bmi @openPortFailed	;This is our flag that the _OpenPort		;in NewPort failed.  If it failed, then		;we don't want to do a _ClosePort on it.	pei portPtr+2	;Close the port, since it opened okay.	pei portPtr	_ClosePort@openPortFailed	lda portHndl+1	beq @notOurPortMem	lda portHndl+2	and #$7FFF	pha	pei portHndl	_DisposeHandle	ldy #2	;If we created a handle for the grafPort	lda #0	;memory, we did this because the portPtr	sta [portDescPtr]	;field was NULL.  If this is the case, we	sta [portDescPtr],y	;need to return it to it's original value.	@notOurPortMem	tsc	;Get rid of local variables.	clc	adc #sizeLocals	tcs	pld	;Restore directPage register.;	lda 1,s	;Move return address.;	sta 1+sizeParms,s;	lda 2,s;	sta 2+sizeParms,s;	tsc	;Get rid of passed parameters.;	adc #sizeParms;	tcs;;	lda #0	;return no error.;	clc;	rtl	ldy #sizeParms	ldx #0	;no error	jml $e10184	;ToStrip	ENDP	endif	END